Definition P_UB_USE_SVC_CONFIG : Z := 0x30e24.
Definition P_UB_CREATE_CONFIG_SVC : Z := 0x30e6c.
Definition USE_SVC_CONFIG_STACK : Z := 32 + DUS_STACK.

Definition use_svc_config_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r owner first fsv lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz fsv) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (dusf_W lo sp r) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ Registry LB m' r owner first 0.

Definition use_svc_config_stmt : Prop :=
  forall (r fsv lo : Z) (LB : list block) (L : list svce) (owner first : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Registry LB m r owner first 0 -> XStatics m ->
  SvcChain m first L -> find_svc L_TYPEID_CONFIG 0 TI_NAME_CONFIG L = fsv -> fsv <> 0 ->
  Forall (svce_off (dusf_W lo sp r)) L ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb8000 <= r) ->
  stk usegs m lo (bv_unsigned sp) -> lo + USE_SVC_CONFIG_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  Forall svce_al L -> r mod 8 = 0 -> fsv mod 8 = 0 ->                                       (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (use_svc_config_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r owner first fsv lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_USE_SVC_CONFIG) fc None m (seg_rom usegs)).
