(* [comment removed for export] *)
Definition P_SC_MID : Z := 0x2fa40.

Definition scA_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (S ioc regb cfgb lo : Z) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (jcem jev jpe jtl : list byte) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' jf j48,
    ms' = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -336)) gp tp t0 t1 t2 (Z_to_bv 64 S) (Z_to_bv 64 0) (Z_to_bv 64 1) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 ioc) s3 (Z_to_bv 64 P_SCHED_GET_DEFAULT_TASK) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_SC_MID) fc None m' (seg_rom usegs)
    /\ munch (sc_W lo sp tp S regb) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -336)
    /\ rw_cells usegs m' (bv_unsigned sp + -336) [CB 280 jf; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells usegs m' S (SvcHdrCells (sched_hdr0 ioc))
    /\ rw_cells usegs m' (S + 48) [C1 (b8 0); C1 (b8 0); CB 6 j48]
    /\ rw_cells usegs m' (S + 56) [CB 56 jcem] /\ rw_cells usegs m' (S + 112) [CB 8 jev]
    /\ rw_cells usegs m' (S + 120) [CB 56 jpe] /\ rw_cells usegs m' (S + 176) [CB 96 jtl]
    /\ sc_inv LB m' ioc regb cfgb tp (wz 0).

Definition sched_ctorA_stmt : Prop :=
  forall (S ioc regb cfgb lo : Z) (LB : list block)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (errv : word) (jh j48 jcem jev jpe jtl : list byte),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  rw_cells usegs m S [CB 48 jh] -> rw_cells usegs m (S + 48) [CB 8 j48] ->
  rw_cells usegs m (S + 56) [CB 56 jcem] -> rw_cells usegs m (S + 112) [CB 8 jev] ->
  rw_cells usegs m (S + 120) [CB 56 jpe] -> rw_cells usegs m (S + 176) [CB 96 jtl] ->
  sc_pure S ioc regb cfgb lo sp tp ra -> sc_inv LB m ioc regb cfgb tp errv ->
  stk usegs m lo (bv_unsigned sp) ->
  mem_inv usegs m ->
  evt usegs (scA_post sp gp tp F fc LB S ioc regb cfgb lo ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 jcem jev jpe jtl m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz S) (wz ioc) (wz 0) (wz P_SCHED_GET_DEFAULT_TASK) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SCHED_CTOR) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
Lemma sc_keep_XS : forall lo sp tp S regb m m',
  XStatics m -> munch (sc_W lo sp tp S regb) m m' -> wmono usegs m m' ->
  hceil <= lo -> (S + 287 <= 0x10000 \/ 0xb8000 <= S) -> (regb + 64 <= 0x10000 \/ 0xb8000 <= regb) -> bv_unsigned tp = RATP ->
  XStatics m'.
Proof.
  intros lo sp tp S regb m m' XS MU WM HC SST RST TPV. hcb. unfold RATP in TPV.
  eapply XStatics_transport; [exact XS| exact MU| exact WM|].
  unfold sc_W, SZ_SCH, O_REG_MUTEX. repeat (apply Forall_cons; [cbn; lia|]). apply Forall_nil.
Qed.

Lemma sc_keep_CAN : forall lo sp tp S regb m m',
  CanaryReads m -> munch (sc_W lo sp tp S regb) m m' ->
  hceil <= lo -> (S + 287 <= 0x10000 \/ 0xb8000 <= S) -> (regb + 64 <= 0x10000 \/ 0xb8000 <= regb) -> bv_unsigned tp = RATP ->
  CanaryReads m'.
Proof.
  intros lo sp tp S regb m m' CAN MU HC SST RST TPV. hcb. unfold RATP in TPV.
  eapply CanaryReads_transport; [exact CAN| exact MU| |]; unfold sc_W, SZ_SCH, O_REG_MUTEX, G_GOT_STACK_CHK, G_STACK_CHK_GUARD; cbn; lia.
Qed.

Lemma sc_keep_CH : forall lo sp tp S regb cfgb ioc m m',
  SvcChain m cfgb [cfg_elt ioc cfgb] -> munch (sc_W lo sp tp S regb) m m' ->
  hceil <= lo -> cfgb + 71 <= lo -> (S + 287 <= cfgb \/ cfgb + 71 <= S) -> (cfgb + 71 <= regb \/ regb + 79 <= cfgb) ->
  (cfgb + 71 <= 0x10000 \/ 0xb8000 <= cfgb) -> (S + 287 <= 0x10000 \/ 0xb8000 <= S) -> (regb + 64 <= 0x10000 \/ 0xb8000 <= regb) ->
  bv_unsigned tp = RATP ->
  SvcChain m' cfgb [cfg_elt ioc cfgb].
