(* [comment removed for export] *)
Ltac fold_registry IN AL :=
  lazymatch goal with |- Registry _ ?mm ?r _ _ _ =>
    lazymatch goal with R0 : rw_cells _ mm r [CB 8 ?j0], RCK : rw_cells _ mm (r + 64) [CB 8 _; CB 7 ?j7], PMC : rw_cells _ mm (r + 8) _, ROF : rw_cells _ mm (r + 48) _ |- _ =>
      lazymatch type of IN with In (?pr, _, _) _ =>
      exists pr, j0, j7; split; [exact IN|]; split; [exact R0|]; split; [apply PMutex_fold; [exact PMC| left; reflexivity| exact AL]|] end;
      split; [exact ROF| unfold CookieCells, zeros; cbn [repeat]; exact RCK] end end.

(* [comment removed for export] *)
Ltac unfold_registry :=
  match goal with REG : Registry _ _ _ _ _ _ |- _ =>
    let p := fresh "p" in let j0 := fresh "j0" in let j7 := fresh "j7" in
    destruct REG as (p & j0 & j7 & _ & ?R0 & ?PM & ?ROF & ?RCK);
    unfold O_REG_MUTEX, O_REG_OWNER, SZ_REG, NEWSZ_REG in R0, PM, ROF, RCK;
    destruct (PMutex_cells _ _ _ PM) as (?PMC & _ & _); clear PM;
    unfold CookieCells, zeros in RCK; cbn [repeat] in RCK end.

(* [comment removed for export] *)
Definition keep (P : Prop) : Prop := P.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac sc_now XS CAN CH0 MU WM :=
  let XSc := fresh "XSc" in let CANc := fresh "CANc" in let CHc := fresh "CHc" in
  lazymatch type of MU with munch _ _ ?mX =>
    lazymatch type of CH0 with keep (SvcChain _ ?c ?L) =>
      assert (XSc : XStatics mX) by (eapply sc_keep_XS; [exact XS| exact MU| exact WM| fast_assumption| fast_assumption| fast_assumption| fast_assumption]);
      assert (CANc : CanaryReads mX) by (eapply sc_keep_CAN; [exact CAN| exact MU| fast_assumption| fast_assumption| fast_assumption| fast_assumption]);
      assert (CHc : SvcChain mX c L) by (eapply sc_keep_CH; [exact CH0| exact MU| fast_assumption| fast_assumption| fast_assumption| fast_assumption| fast_assumption| fast_assumption| fast_assumption| fast_assumption])
    end end.

Ltac sc_clear_now := try match goal with X : XStatics _ |- _ => clear X end;
  repeat match goal with X : CanaryReads _ |- _ => clear X end;
  repeat match goal with X : SvcChain _ _ _ |- _ => clear X end.

(* [comment removed for export] *)
Ltac sc_side0 INR AL :=
  lazymatch goal with
  | |- Registry _ _ _ _ _ _ => first [fast_assumption | fold_registry INR AL]
  | |- _ <> 0 -> _ => intros _; split; [apply XS_tiname_config; fast_assumption | unfold L_TYPEID_CONFIG; lia]
  | |- SvcChain _ _ _ => fast_assumption
  | |- find_svc _ _ _ _ = _ => apply cfg_find
  | |- Forall svce_al _ => apply Forall_cons; [split; [fast_assumption| intros _; unfold cfg_elt, cfg_hdr, L_TYPEID_CONFIG; cbn; reflexivity] | apply Forall_nil]
  | |- Forall _ _ => apply Forall_cons; [unfold svce_off, dusf_W, cfg_elt, O_REG_MUTEX, NEWSZ_CFG, NEWSZ_REG; cbn; rewrite ?unsigned_lit by lia; lia| apply Forall_nil]
  | |- stk _ _ _ _ => rewrite ?unsigned_lit by lia; fast_assumption
  | |- CanaryReads _ => fast_assumption
  | |- XStatics _ => fast_assumption
  | |- mem_inv _ _ => fast_assumption
  | |- rw_cells _ _ _ _ => fast_eassumption
  | |- ro_cells _ _ _ _ => fast_eassumption
  | |- gv_null _ = true => reflexivity
  | |- _ = _ => first [ fast_assumption | reflexivity | rewrite ?unsigned_lit by lia; first [reflexivity | Z.div_mod_to_equations; lia] ]
  | |- _ => unfold L_TYPEID_CONFIG, TI_NAME_CONFIG, USE_SVC_CONFIG_STACK, DUS_STACK, SLOCK_DTOR_STACK, MUTEX_UNLOCK_STACK, CONFIG_GET_STACK,
                 GET_VALUE_STACK, SNPRINTF_STACK, SZ_CFG, NEWSZ_CFG, SZ_REG, NEWSZ_REG, NEWSZ_SCH;
          rewrite ?unsigned_lit by lia; lia
  end.
Ltac sc_side INR AL := first [ sc_side0 INR AL | match goal with |- ?G => idtac "SIDE-FAIL" G; fail end ].

(* [comment removed for export] *)
Ltac sc_usc regb cfgb lo LB ioc INR AL XS CAN CH0 MU WM :=
  unfold wz; sc_now XS CAN CH0 MU WM;
  let D := fresh "D" in let REGc := fresh "REGc" in
  pose proof use_svc_config_spec as D; unfold use_svc_config_stmt, wz, P_UB_USE_SVC_CONFIG in D;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    assert (REGc : Registry LB mm regb ioc cfgb 0) by (fold_registry INR AL);
    repeat match goal with X : rw_cells _ mm regb _ |- _ => clear X | X : rw_cells _ mm (regb + _) _ |- _ => clear X end;
    eapply evt_cut;
    [ eapply (D regb cfgb lo LB [cfg_elt ioc cfgb] ioc cfgb); sc_side INR AL
    | intros ms' PO; unfold use_svc_config_post, dusf_W, O_REG_MUTEX in PO; rewrite ?unsigned_lit in PO by lia;
      revert ms' PO; post_call usegs mm ] end;
  clear D; try clear REGc; sc_clear_now; unfold_registry.

(* [comment removed for export] *)
Ltac sc_cg CG cfgb lo INR AL XS CAN CH0 MU WM :=
  unfold wz; sc_now XS CAN CH0 MU WM;
  let C := fresh "CGL" in
  pose proof CG as C; unfold cg_stmt in C; cbn [key_lit] in C;
  unfold wz, L_STR_SCHEDULER, L_STR_CONCURRENCY_HINT, L_STR_ASSUME_CONT, L_STR_LOCKING, L_STR_SPIN, L_STR_TASK_USEC, L_STR_WAIT_USEC,
         P_CONFIG_GET_INT, P_CONFIG_GET_BOOL, P_CONFIG_GET_LONG, O_CFG_HINT in C;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    eapply evt_cut; [ eapply (C cfgb lo); sc_side INR AL | post_callZ usegs mm ] end;
  clear C; sc_clear_now.

